/usr/bin/bash -lc "nl -ba PROVENANCE.json | sed -n '1,85p'; nl -ba lean/claims.yaml | sed -n '1,22p'; python3 - <<'PY'
from pathlib import Path
import re,collections
lines=Path('candidate/statement-ledger.md').read_text().splitlines()
claims=Path('lean/claims.yaml').read_text().splitlines()
module=None; found=collections.defaultdict(list)
for i,l in enumerate(lines,1):
 if l.startswith('## '):module=l[3:]
 if l.startswith('|'):
  m=re.search(r'"'`(StratonovichHAM(?:Audit|SecondMoment)'"\\.["'^`]+)`'"',l)
  if m:found[module].append((i,m[1],l.split('|')[1].strip()))
for k,v in found.items():print(k, len(v), 'labelled',sum(not a[2].startswith('no direct label') for a in v))
for i,l in enumerate(claims,1):
 if l=='  status: internal':
  print(i, next(x for x in reversed(claims[:i]) if x.startswith('  decl: ')))
PY"

